using namespace std;

struct Point { int x, y; };

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    vector<Point> p(N);
    for (int i = 0; i < N; ++i) {
        cin >> p[i].x >> p[i].y;
    }

    vector<uint64_t> edges;
    edges.reserve(N * N);

    auto pack = [](int u, int v, int w) {
        return (uint64_t(uint32_t(w)) << 32) |
               (uint64_t(uint32_t(u)) << 16) |
               uint64_t(uint32_t(v));
    };

    for (int v = 0; v < N; ++v) {
        int d = p[v].x * p[v].x + p[v].y * p[v].y;
        edges.push_back(pack(N, v, d));
    }

    for (int u = 0; u < N; ++u) {
        for (int v = 0; v < N; ++v) {
            if (u == v) continue;
            int dx = p[u].x - p[v].x;
            int dy = p[u].y - p[v].y;
            int d = dx * dx + dy * dy;
            edges.push_back(pack(u, v, d));
        }
    }

    sort(edges.begin(), edges.end(), [](uint64_t a, uint64_t b) {
        return a > b;
    });

    const int NEG = -1000000000;
    vector<int> best(N, NEG);
    int ans = 0;
    vector<int> vals;

    for (size_t i = 0; i < edges.size(); ) {
        int L = (int)(edges[i] >> 32);
        size_t j = i + 1;
        while (j < edges.size() && (int)(edges[j] >> 32) == L) ++j;

        size_t cnt = j - i;
        vals.resize(cnt);

        for (size_t k = i; k < j; ++k) {
            uint64_t e = edges[k];
            int u = (int)((e >> 16) & 0xFFFF);
            int v = (int)(e & 0xFFFF);

            int val;
            if (u == N) {
                val = 1;
            } else {
                if (best[u] == NEG) val = NEG;
                else val = best[u] + 1;
            }

            vals[k - i] = val;
            if (val > ans) ans = val;
        }

        for (size_t k = i; k < j; ++k) {
            uint64_t e = edges[k];
            int v = (int)(e & 0xFFFF);
            int val = vals[k - i];
            if (val > best[v]) best[v] = val;
        }

        i = j;
    }

    cout << ans << '\n';
    return 0;
}
